SELECT [Станции_для_сводной(архив)].*, [Станции_по_углям_2(архив)].topl, [Станции_по_углям_2(архив)].pertop, [nust]*[pertop]/100 AS dnust, [e]*[pertop]/100 AS DE, [Станции_по_углям_2(архив)].rtop
FROM [Станции_по_углям_2(архив)] INNER JOIN [Станции_для_сводной(архив)] ON ([Станции_по_углям_2(архив)].NUMB1120=[Станции_для_сводной(архив)].numb1120) AND ([Станции_по_углям_2(архив)].YEAR=[Станции_для_сводной(архив)].year);
